/* ---------- favorieten (tijdlijntitels) ---------- */
var FKEY="onk-tl-favs",FIDX=null,bwSig="";
function favs(){try{var a=JSON.parse(localStorage.getItem(FKEY)||"[]");return Array.isArray(a)?a:[]}catch(e){return[]}}
