   '<button class="otl-x" id="otl-close" type="button"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg></button>'+
   '<div class="otl-vsw" id="otl-vsw"></div><div class="otl-sel" id="otl-sel"></div><div class="otl-mode" id="otl-mode"><button type="button" data-m="ch"></button><button type="button" data-m="bk"></button><button type="button" data-m="fv"></button></div></div>'+
   '<div class="otl-pb"><div class="otl-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input id="otl-q" autocomplete="off"></div><div id="otl-body"></div></div>'+
   '</div>';
  document.body.appendChild(a);
