  if(single){
    E.forEach(function(e){e.sub.forEach(function(s){s.refs.forEach(function(r){if(!(r[0] in cm))cm[r[0]]=eras.indexOf(L(e.era))})})});
    var cols=["#dfe8ec","#e8e3d3","#dde9e0"];
    h+='<div class="otl-strip">';
    for(var k=1;k<=N;k++)h+='<button type="button" class="'+(cur&&k===S.ch?"c":"e"+(cm[k]%3))+'" data-code="'+code+'" data-sc="'+k+'" title="'+bookName(code)+" "+k+'">'+k+"</button>";
    h+='</div>'+(eras.length>1?'<div class="otl-legend">'+eras.map(function(x,k){return '<span><i style="background:'+cols[k%3]+'"></i>'+esc(x)+"</span>"}).join("")+"</div>":"")}
